"""Truck Capacity

A delivery truck departs each morning with a sequence of packages that must be delivered in the exact order they are lined up, with no skipping or reordering.
The truck can make several trips, but on any single trip it can only carry a total weight up to some fixed capacity.
The company wants to set the truck's capacity just low enough while still completing all deliveries within maxTrips trips.
Write a function that, given the package weights in order and the maximum allowed trips, returns the smallest capacity that permits all packages to be delivered within maxTrips trips.
If it's impossible (e.g., no trips allowed or no packages), return -1.
"""

import math

def minTruckCapacity(packages, maxTrips):
    """Return the minimum capacity needed, or -1 if impossible."""
    if not packages or not maxTrips:
        return -1
    min_capacity = max(packages)
    ratio = len(packages) / maxTrips
    max_capacity = min_capacity * math.ceil(ratio)

    def works(capacity):
        trips = 1
        used = 0
        for package in packages:
            if package + used > capacity:
                used = 0
                trips += 1
                if trips > maxTrips:
                    return False
            used += package
        return trips <= maxTrips

    while min_capacity < max_capacity:
        check = (min_capacity + max_capacity) // 2
        if works(check):
            max_capacity = check
        else:
            min_capacity = check + 1
    return min_capacity


assert minTruckCapacity([1, 2, 3, 4, 5], 3) == 6
assert minTruckCapacity([3, 2, 2, 4, 1, 4], 3) == 6
assert minTruckCapacity([], 3) == -1
assert minTruckCapacity([1, 2, 3], 0) == -1
